using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Tests
{
    public class OpenAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddOpenAITextEmbeddingGeneration_Should_Call_GetService_ILoggerFactory()
        {
            // Arrange
            var services = new ServiceCollection();

            var mockLoggerFactory = new Mock<ILoggerFactory>();
            var mockServiceProvider = new Mock<IServiceProvider>();
            mockServiceProvider
                .Setup(sp => sp.GetService(typeof(ILoggerFactory)))
                .Returns(mockLoggerFactory.Object);

            // Setup IServiceCollection to return itself for AddKeyedSingleton
            var wasCalled = false;
            services.AddKeyedSingleton<ITextEmbeddingGenerationService>("testService", (sp, _) =>
            {
                wasCalled = true;
                // Verify that the service provider passed here is our mock
                Assert.Equal(mockServiceProvider.Object, sp);
                return null; // Not used further
            });

            // Act
            // Manually invoke the extension method with the mocked service provider
            var result = OpenAIServiceCollectionExtensions.AddOpenAITextEmbeddingGeneration(
                services,
                "model-id",
                "api-key",
                orgId: null,
                serviceId: "testService",
                dimensions: 128);

            // Assert
            Assert.NotNull(result);
            Assert.Contains(result, s => s == services);
        }
    }
}
